import{_ as i,I as n,o as t,c as d,a6 as a,b as r,w as o,a as c,J as l,a7 as h,ac as p,ad as g,ae as m,af as u,ag as b,ah as f,ai as k,aj as y,ak as w,al as v,am as x,an as C,ao as S,ap as T,aq as E,ar as _,as as A,at as P,au as L,av as M,aw as R,ax as I}from"./chunks/framework.ZMCvXf1_.js";const V=JSON.parse('{"title":"Terminal UI","description":"","frontmatter":{},"headers":[],"relativePath":"tui.md","filePath":"tui.md"}'),z={name:"tui.md"};function D(N,e,B,F,Q,q){const s=n("Mermaid");return t(),d("div",null,[e[1]||(e[1]=a('<h1 id="terminal-ui" tabindex="-1">Terminal UI <a class="header-anchor" href="#terminal-ui" aria-label="Permalink to “Terminal UI”">​</a></h1><p>Launch the interactive terminal interface with:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ui</span></span></code></pre></div><p><img src="'+p+'" alt="A full pass through the TUI: adding a config, creating the database, building the schema, fast-forwarding changes, and browsing the result in the explorer" loading="lazy"></p><p>Everything in noorm is accessible through keyboard shortcuts. The mouse works too, in lists and grids — see <a href="#mouse">Mouse</a> if you would rather it did not.</p><p>The TUI is a dedicated subcommand — every other <code>noorm</code> command runs as a non-interactive CLI. Running <code>noorm</code> on its own prints the command list (citty&#39;s <code>--help</code>) instead of opening the wizard, so the entry into the TUI is always explicit. See the <a href="/headless.html">CLI Reference</a> for the headless surface.</p><h2 id="home-screen" tabindex="-1">Home Screen <a class="header-anchor" href="#home-screen" aria-label="Permalink to “Home Screen”">​</a></h2><p><img src="'+g+`" alt="The noorm TUI home screen: status, quick actions, and recent activity" loading="lazy"></p><h2 id="navigation-map" tabindex="-1">Navigation Map <a class="header-anchor" href="#navigation-map" aria-label="Permalink to “Navigation Map”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>                              ┌─────────┐</span></span>
<span class="line"><span>                              │  Home   │</span></span>
<span class="line"><span>                              └────┬────┘</span></span>
<span class="line"><span>        ┌──────────┬──────────┬────┴────┬──────────┐</span></span>
<span class="line"><span>        │          │          │         │          │</span></span>
<span class="line"><span>     [c]│       [g]│       [r]│      [d]│       [s]│</span></span>
<span class="line"><span>        ▼          ▼          ▼         ▼          ▼</span></span>
<span class="line"><span>   ┌────────┐ ┌────────┐ ┌────────┐ ┌────────┐ ┌────────┐</span></span>
<span class="line"><span>   │ Config │ │ Change │ │  Run   │ │Database│ │Settings│</span></span>
<span class="line"><span>   │  List  │ │  List  │ │  Menu  │ │  Menu  │ │  Menu  │</span></span>
<span class="line"><span>   └────────┘ └────────┘ └────────┘ └────────┘ └────────┘</span></span>
<span class="line"><span>        │          │          │         │</span></span>
<span class="line"><span>        │          │          │         ├── Explore (tables, views...)</span></span>
<span class="line"><span>        │          │          │         └── Terminal (SQL REPL)</span></span>
<span class="line"><span>        │          │          │</span></span>
<span class="line"><span>        │          │          └── Build, File, Directory, Exec, Inspect</span></span>
<span class="line"><span>        │          │</span></span>
<span class="line"><span>        │          └── FF, Next, Run, Revert, Rewind, History</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├── Add, Edit, Delete, Copy, Use</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        └──[k]── Secrets List</span></span></code></pre></div><p>Secrets hang off a config, so <code>k</code> opens them from the Config List, not from Home. Export, import, and validate sit behind <code>[+] More</code> on the Config List.</p><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to “Keyboard Shortcuts”">​</a></h2><h3 id="home-navigation" tabindex="-1">Home Navigation <a class="header-anchor" href="#home-navigation" aria-label="Permalink to “Home Navigation”">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Screen</th><th>Description</th></tr></thead><tbody><tr><td><code>r</code></td><td>Run</td><td>Execute schema files</td></tr><tr><td><code>c</code></td><td>Config</td><td>Manage database connections</td></tr><tr><td><code>g</code></td><td>Changes</td><td>View and apply changes</td></tr><tr><td><code>d</code></td><td>Database</td><td>Explore schema, run queries</td></tr><tr><td><code>+</code></td><td>More</td><td>Settings, vault, identity, lock</td></tr><tr><td><code>s</code></td><td>Settings</td><td>Project configuration</td></tr><tr><td><code>v</code></td><td>Vault</td><td>Team-shared encrypted secrets</td></tr><tr><td><code>i</code></td><td>Identity</td><td>View/edit your identity</td></tr><tr><td><code>l</code></td><td>Lock</td><td>View/manage database locks</td></tr><tr><td><code>u</code></td><td>Update</td><td>Check for a newer noorm</td></tr><tr><td><code>q</code></td><td>—</td><td>Quit noorm</td></tr></tbody></table><p><code>s</code>, <code>v</code>, <code>i</code>, and <code>l</code> work from Home directly as well as from <code>[+] More</code>. Three number keys run the quick actions listed on the home screen:</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>1</code></td><td>Run build</td></tr><tr><td><code>2</code></td><td>Apply changes (fast-forward)</td></tr><tr><td><code>3</code></td><td>View lock status</td></tr></tbody></table><p>Per-config <strong>secrets</strong> are not on this list — they hang off a config rather than the project, so you reach them with <code>k</code> from the config list.</p><h3 id="common-actions-in-sub-screens" tabindex="-1">Common Actions (in sub-screens) <a class="header-anchor" href="#common-actions-in-sub-screens" aria-label="Permalink to “Common Actions (in sub-screens)”">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Action</th><th>Available In</th></tr></thead><tbody><tr><td><code>a</code></td><td>Add new</td><td>Config, Changes, Secrets</td></tr><tr><td><code>e</code></td><td>Edit</td><td>Config, Changes, Secrets</td></tr><tr><td><code>d</code></td><td>Delete</td><td>Config, Changes, Secrets</td></tr><tr><td><code>c</code></td><td>Copy</td><td>Config</td></tr><tr><td><code>k</code></td><td>Secrets</td><td>Config (secrets for the highlighted config)</td></tr><tr><td><code>+</code></td><td>More</td><td>Config (export, import, validate)</td></tr><tr><td><code>Enter</code></td><td>Use/Activate</td><td>Config (set as active)</td></tr></tbody></table><p>Export, import, and validate live behind <code>[+] More</code> on the config list rather than on the list itself, which keeps the destructive and the routine actions apart.</p><h3 id="list-navigation" tabindex="-1">List Navigation <a class="header-anchor" href="#list-navigation" aria-label="Permalink to “List Navigation”">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code></td><td>Move up</td></tr><tr><td><code>↓</code></td><td>Move down</td></tr><tr><td><code>Enter</code></td><td>Select</td></tr><tr><td><code>Escape</code></td><td>Go back</td></tr><tr><td><code>1</code>-<code>9</code></td><td>Quick select by number, on lists that show numbers</td></tr></tbody></table><p>Numbered selection is enabled per list — if a list renders numbers down its left edge (Settings and the schema explorer do), the digits work there.</p><p>Every list sizes itself to the window, so a taller terminal shows more rows rather than the same fixed count with the rest behind a scroll marker. A list also keeps its cursor when you open an item and come back, so walking a long list one entry at a time does not restart at the top.</p><h3 id="form-navigation" tabindex="-1">Form Navigation <a class="header-anchor" href="#form-navigation" aria-label="Permalink to “Form Navigation”">​</a></h3><p>Forms have two modes and <code>Enter</code> switches between them.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Key</th><th>Effect</th></tr></thead><tbody><tr><td>Browse</td><td><code>↑</code> <code>↓</code></td><td>Move between fields, every field type included</td></tr><tr><td>Browse</td><td><code>Tab</code> / <code>Shift+Tab</code></td><td>Same, forwards and backwards</td></tr><tr><td>Browse</td><td><code>Enter</code></td><td>Open the active field for editing</td></tr><tr><td>Browse</td><td><code>Escape</code></td><td>Cancel the form</td></tr><tr><td>Edit</td><td><code>Enter</code></td><td>Commit and return to browse</td></tr><tr><td>Edit</td><td><code>Escape</code></td><td>Restore the value the field held when edit opened</td></tr><tr><td>Edit</td><td><code>Tab</code></td><td>Commit and move to the next field</td></tr></tbody></table><p>Enter is the mode switch, so submitting is a place you navigate to rather than a key you press:</p>`,28)),(t(),r(h,null,{default:o(()=>[l(s,{id:"mermaid-483",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20Browse%0A%20%20%20%20Browse%20--%3E%20Edit%3A%20Enter%20on%20a%20text%20or%20select%20field%0A%20%20%20%20Edit%20--%3E%20Browse%3A%20Enter%20commits%0A%20%20%20%20Edit%20--%3E%20Browse%3A%20Esc%20reverts%0A%20%20%20%20Browse%20--%3E%20Actions%3A%20Down%20past%20the%20last%20field%0A%20%20%20%20Actions%20--%3E%20Browse%3A%20Down%20wraps%20to%20the%20first%20field%0A%20%20%20%20Actions%20--%3E%20%5B*%5D%3A%20Enter%20on%20the%20submit%20button%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<p>Past the last field the cursor lands on the action row, where <code>←</code> <code>→</code> move between the buttons and <code>Enter</code> activates one. The submit button carries the screen&#39;s own label, <code>[ Create Config ]</code> on the add-config form.</p><p>Two field types never open into edit mode:</p><ul><li>A <strong>checkbox</strong> toggles in place on <code>Enter</code> or <code>Space</code>.</li><li>A <strong>select</strong> expands on <code>Enter</code>, moves with <code>↑</code> <code>↓</code>, and takes the highlighted option on a second <code>Enter</code>. Collapsed, it shows its current value on one line like every other field.</li></ul><p>A red <code>*</code> after a label marks a required field. Submitting with one empty puts the cursor on it and shows the error beside the value.</p><h3 id="mouse" tabindex="-1">Mouse <a class="header-anchor" href="#mouse" aria-label="Permalink to “Mouse”">​</a></h3><p>On by default, in lists and result grids only:</p><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td>Click a row</td><td>Move the cursor to it</td></tr><tr><td>Double-click a row</td><td>Same as <code>Enter</code> on that row</td></tr><tr><td>Wheel up / down</td><td>Move the cursor one row</td></tr></tbody></table><p>A click acts on whatever already has focus. Clicking a list that is not focused does nothing — it does not move focus there, so the keyboard stays where you left it.</p><h4 id="text-selection-stopped-working" tabindex="-1">Text selection stopped working <a class="header-anchor" href="#text-selection-stopped-working" aria-label="Permalink to “Text selection stopped working”">​</a></h4><p>That is this feature, and it is the one thing it costs you. Any terminal mouse-tracking mode hands the mouse to the application, so click-drag selection needs a modifier held down: Option in macOS Terminal and iTerm2, Shift in most others.</p><p>If you would rather have plain selection back, turn the mouse off in <code>.noorm/settings.yml</code>:</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    mouse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p><code>?</code> inside the TUI prints the same line, so you do not have to remember which file it lives in. Nothing else changes: every screen is fully keyboard-driven either way.</p><h3 id="global-shortcuts" tabindex="-1">Global Shortcuts <a class="header-anchor" href="#global-shortcuts" aria-label="Permalink to “Global Shortcuts”">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Shift+L</code></td><td>Toggle log viewer overlay</td></tr><tr><td><code>Shift+Q</code></td><td>Open the SQL terminal</td></tr><tr><td><code>?</code></td><td>Show help</td></tr><tr><td><code>Escape</code></td><td>Go back / Cancel</td></tr><tr><td><code>Ctrl+C</code></td><td>Quit</td></tr></tbody></table><h3 id="cancelling-a-database-operation" tabindex="-1">Cancelling a Database Operation <a class="header-anchor" href="#cancelling-a-database-operation" aria-label="Permalink to “Cancelling a Database Operation”">​</a></h3><p>A screen waiting on a database says so, and says that <code>Escape</code> will stop it:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Testing connection...  [Esc] Cancel</span></span></code></pre></div><p>That appears while a config is being tested (add and edit), while the force-release screen checks lock status, and while the SQL terminal connects or runs a query. <code>Escape</code> returns the screen to a usable state; nothing is saved.</p><p>Two things are worth knowing about what &quot;cancel&quot; means here:</p><ul><li><strong>The client always stops waiting. The server usually does not stop working.</strong> A cancelled query keeps running on PostgreSQL and MySQL only until noorm&#39;s cancel request reaches it, and on SQL Server and SQLite it is never told at all. The message names which happened, and <a href="./guide/database/terminal.html">the SQL terminal guide</a> has the per-dialect table.</li><li><strong>A connect that answers after you cancelled is closed, not adopted.</strong> The screen keeps the state you cancelled into, and the connection is destroyed rather than left half-open.</li></ul><p>A connection attempt also ends on its own after 15 seconds, with or without a keypress. Raise <code>connection.connectTimeoutMs</code> for a link that is slow but working.</p><h2 id="screen-reference" tabindex="-1">Screen Reference <a class="header-anchor" href="#screen-reference" aria-label="Permalink to “Screen Reference”">​</a></h2><h3 id="config-list" tabindex="-1">Config List <a class="header-anchor" href="#config-list" aria-label="Permalink to “Config List”">​</a></h3><p><img src="`+m+'" alt="The configuration list screen" loading="lazy"></p><ul><li><code>●</code> indicates active config</li><li><code>○</code> indicates inactive config</li><li><code>&gt;</code> indicates cursor position</li><li><code>[user:&lt;role&gt; agent:&lt;role|off&gt;]</code> tag shows access roles for any config whose access differs from the default (<code>user: admin</code>, <code>agent: viewer</code>) — omitted entirely for configs still on the default</li><li><code>[test]</code> tag shows test configs</li><li>Press <code>Enter</code> on a config to activate it</li></ul><p>Press <code>a</code> to add one. Adding a config is the one operation that is interactive only — <code>noorm config add</code> on the CLI directs you here:</p><p><img src="'+u+'" alt="The add-config form: name, dialect, connection details, and per-channel access roles" loading="lazy"></p><p>The two role fields set access per <strong>channel</strong> — who is <em>driving</em>. <code>User Role</code> covers a human on the CLI, TUI, or SDK; <code>Agent Role</code> covers an AI agent, over MCP and the CLI alike. They are independent, so a config can be wide open at your terminal and read-only — or invisible — to an agent. New configs default to <code>admin</code> for you and <code>viewer</code> for the agent. See <a href="/guide/environments/configs.html#access-roles">Configs</a> for what each role permits.</p><h3 id="changes-list" tabindex="-1">Changes List <a class="header-anchor" href="#changes-list" aria-label="Permalink to “Changes List”">​</a></h3><p><img src="'+b+'" alt="The changes list, showing applied and pending changes" loading="lazy"></p><ul><li><code>✓</code> = Applied</li><li><code>○</code> = Pending</li><li><code>✗</code> = Failed</li></ul><p>When no changes exist:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>No changes found. Press [a] to create one.</span></span></code></pre></div><p>Press <code>h</code> for the execution history — what ran, when, and who ran it:</p><p><img src="'+f+'" alt="Change execution history, with per-change status and the identity that applied it" loading="lazy"></p><h3 id="run-menu" tabindex="-1">Run Menu <a class="header-anchor" href="#run-menu" aria-label="Permalink to “Run Menu”">​</a></h3><p><img src="'+k+'" alt="The run menu" loading="lazy"></p><h3 id="database-menu" tabindex="-1">Database Menu <a class="header-anchor" href="#database-menu" aria-label="Permalink to “Database Menu”">​</a></h3><p><img src="'+y+'" alt="The database operations menu" loading="lazy"></p><h3 id="schema-explorer" tabindex="-1">Schema Explorer <a class="header-anchor" href="#schema-explorer" aria-label="Permalink to “Schema Explorer”">​</a></h3><p><img src="'+w+'" alt="The schema explorer overview, with object counts by category" loading="lazy"></p><p>Press a number to drill into a category:</p><p><img src="'+v+'" alt="The explorer table list" loading="lazy"></p><p>Select a table to see its full schema:</p><p><img src="'+x+'" alt="Table detail: columns, indexes, and foreign keys" loading="lazy"></p><p>A detail longer than the window scrolls rather than running off the bottom:</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> <code>↓</code></td><td>Scroll one line</td></tr><tr><td><code>Ctrl+U</code> / <code>Ctrl+D</code></td><td>Half a page</td></tr><tr><td><code>PageUp</code> / <code>PageDown</code></td><td>A full page. On macOS these are <code>fn ↑</code> and <code>fn ↓</code>, which is what the footer says there</td></tr><tr><td><code>Home</code> / <code>End</code></td><td>Top, bottom</td></tr><tr><td><code>v</code></td><td>Redraw the same rows with nothing truncated</td></tr><tr><td><code>r</code></td><td>Read rows from the object</td></tr></tbody></table><p>The footer lists only the keys the current screen answers to, so a detail that fits shows no scroll hints and a view shows no <code>[r] Rows</code>.</p><h3 id="reading-rows" tabindex="-1">Reading Rows <a class="header-anchor" href="#reading-rows" aria-label="Permalink to “Reading Rows”">​</a></h3><p>The explorer describes structure. <code>r</code> on a detail screen reads the rows themselves, without leaving the explorer for the SQL terminal:</p><p><img src="'+C+'" alt="Peeking at both ends of a table, then opening one row as a document" loading="lazy"></p><p>The peek reads both ends of the table rather than a page from the top, so the last rows by primary key are as reachable as the first:</p><p><img src="'+S+'" alt="The row peek: first rows and last rows, side by side" loading="lazy"></p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> <code>↓</code></td><td>Move the cursor within a set</td></tr><tr><td><code>Tab</code></td><td>Swap between the first set and the last</td></tr><tr><td><code>Enter</code></td><td>Open the highlighted row as a document</td></tr><tr><td><code>/</code> <code>s</code> <code>c</code></td><td>Filter, sort, clear, on the focused set</td></tr><tr><td><code>Escape</code></td><td>Close the peek</td></tr></tbody></table><p>Three things decide what comes back:</p><ul><li><strong>Reading rows needs <code>sql:read</code></strong>, not the <code>explore</code> permission the rest of these screens use. A config an agent may inspect the schema of is not one it may read data from. See <a href="/guide/environments/configs.html#access-roles">Configs</a>.</li><li><strong>The tail needs a primary key.</strong> With one, the last rows ride the index. Without one, only the first rows appear.</li><li><strong>A short table is one set.</strong> When both ends meet, the peek says <code>All N rows</code> and draws a single table.</li></ul><p>The table fits as many whole columns as the terminal holds and marks the rest <code>… N more columns</code>. <code>Enter</code> on a row is what shows them all:</p><p><img src="'+T+'" alt="One row as a YAML document, with the keys to walk to the next" loading="lazy"></p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>←</code> <code>→</code></td><td>Previous row, next row, in the order the table was showing</td></tr><tr><td><code>↑</code> <code>↓</code></td><td>Scroll a document taller than the window</td></tr><tr><td><code>f</code></td><td>Swap YAML for JSON. The choice holds for the rest of the session</td></tr><tr><td><code>Escape</code></td><td>Back to the peek, on the row you were reading</td></tr></tbody></table><h3 id="sql-terminal" tabindex="-1">SQL Terminal <a class="header-anchor" href="#sql-terminal" aria-label="Permalink to “SQL Terminal”">​</a></h3><p>Press <code>Shift+Q</code> anywhere to open the SQL terminal against the active config:</p><p><img src="'+E+'" alt="The built-in SQL terminal" loading="lazy"></p><ul><li><code>↑</code> <code>↓</code> walk your query history, and <code>h</code> opens it as a list</li><li>A result wider than the terminal keeps whole columns and marks the remainder <code>… N more columns</code>, rather than cramming every column into a few characters</li><li><code>Enter</code> on a result row opens it as a document, the same YAML or JSON view the row peek uses, which is how you read the columns the grid left out</li></ul><h3 id="log-viewer" tabindex="-1">Log Viewer <a class="header-anchor" href="#log-viewer" aria-label="Permalink to “Log Viewer”">​</a></h3><p>Press <code>Shift+L</code> anywhere to toggle the log overlay:</p><p><img src="'+_+'" alt="The log viewer overlay, opened with Shift+L" loading="lazy"></p><p>The overlay tails events as they happen, so you can watch an operation run. <code>[/]</code> searches, <code>[g]</code> and <code>[G]</code> jump to the top and bottom, <code>[Space]</code> pauses the tail, <code>[Enter]</code> opens a single entry in full, and <code>Shift+L</code> again closes it.</p><h3 id="more-options" tabindex="-1">More Options <a class="header-anchor" href="#more-options" aria-label="Permalink to “More Options”">​</a></h3><p>Press <code>+</code> from home for the screens that aren&#39;t part of the day-to-day loop:</p><p><img src="'+A+'" alt="The More Options menu: settings, vault, identity, and lock" loading="lazy"></p><p>Each of these also has a direct key from home — <code>+</code> just groups them.</p><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to “Settings”">​</a></h3><p><img src="'+P+'" alt="The settings screen, listing the seven setting groups" loading="lazy"></p><p>Edits here write to <code>.noorm/settings.yml</code>. Press <code>i</code> to create that file if the project doesn&#39;t have one yet. See <a href="/guide/environments/configs.html">Configs</a> and <a href="/guide/sql-files/organization.html">SQL File Organization</a> for what each group controls.</p><h3 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to “Identity”">​</a></h3><p><img src="'+L+'" alt="The identity screen, showing the current keypair and fingerprint" loading="lazy"></p><p>Your identity signs your name to every change execution, which is what makes <a href="/guide/changes/history.html">change history</a> attributable across a team. It lives in <code>~/.noorm/</code>, not in the project, so it follows you between repositories.</p><h3 id="vault" tabindex="-1">Vault <a class="header-anchor" href="#vault" aria-label="Permalink to “Vault”">​</a></h3><p><img src="'+M+'" alt="The vault screen before initialization" loading="lazy"></p><p>The vault holds team-shared encrypted secrets in the database itself, so teammates get them by connecting rather than by copying a <code>.env</code> around. It starts uninitialized — press <code>i</code> to create it. See <a href="/guide/environments/vault.html">Vault</a>.</p><h3 id="secrets" tabindex="-1">Secrets <a class="header-anchor" href="#secrets" aria-label="Permalink to “Secrets”">​</a></h3><p>Per-config secrets are reached with <code>k</code> from the config list, not from home — they belong to a config rather than to the project:</p><p><img src="'+R+'" alt="The secrets screen for a config" loading="lazy"></p><p>These are values a config needs at connection or render time. See <a href="/guide/environments/secrets.html">Secrets</a> for how they resolve against stages.</p><h3 id="lock" tabindex="-1">Lock <a class="header-anchor" href="#lock" aria-label="Permalink to “Lock”">​</a></h3><p><img src="'+I+'" alt="The lock screen, showing current lock state" loading="lazy"></p><p>noorm takes a lock around operations that write to the database, so two people running a build against the same environment don&#39;t interleave. <code>[s]</code> shows status, <code>[a]</code> acquires, <code>[r]</code> releases, and <code>[f]</code> force-breaks a stale lock. See <a href="/dev/lock.html">Locking</a>.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to “Tips”">​</a></h2><h3 id="quick-config-switching" tabindex="-1">Quick Config Switching <a class="header-anchor" href="#quick-config-switching" aria-label="Permalink to “Quick Config Switching”">​</a></h3><p>From home, press <code>c</code>, arrow to the config you want, then <code>Enter</code> to activate it. The config list is not numbered, so the digits do nothing there:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>c → ↓ → Enter</span></span></code></pre></div><p><code>Enter</code> on the config that is <em>already</em> active opens its edit form instead.</p><h3 id="fast-forward-all-changes" tabindex="-1">Fast Forward All Changes <a class="header-anchor" href="#fast-forward-all-changes" aria-label="Permalink to “Fast Forward All Changes”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>g → f</span></span></code></pre></div><h3 id="run-build" tabindex="-1">Run Build <a class="header-anchor" href="#run-build" aria-label="Permalink to “Run Build”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>r → b</span></span></code></pre></div><h3 id="check-connection" tabindex="-1">Check Connection <a class="header-anchor" href="#check-connection" aria-label="Permalink to “Check Connection”">​</a></h3><p>Validate lives behind <code>[+] More</code> on the config list:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>c → + → v (validate highlighted config)</span></span></code></pre></div><h2 id="color-coding" tabindex="-1">Color Coding <a class="header-anchor" href="#color-coding" aria-label="Permalink to “Color Coding”">​</a></h2><table tabindex="0"><thead><tr><th>Color</th><th>Meaning</th></tr></thead><tbody><tr><td>Green</td><td>Success, applied, active</td></tr><tr><td>Yellow</td><td>Warning, pending, in progress</td></tr><tr><td>Red</td><td>Error, failed</td></tr><tr><td>Gray</td><td>Skipped, unchanged</td></tr><tr><td>Cyan</td><td>Info, links</td></tr></tbody></table>',102))])}const U=i(z,[["render",D]]);export{V as __pageData,U as default};
